import logging
import random
import re
import time
from datetime import datetime
from moler.device import DeviceFactory
from taf.rfrl.utilities.tl_config import load_moler_configuration_from_tl
from taf.rfrl.utilities.robot.general import get_builtin_value
from moler.exceptions import MolerException
from taf.rfrl.ue.iperf.tput_validation import ThroughputValidation, UnknownUeType, NoAvailableUesException
from taf.rfrl.ue.custom_ues import AndroidUe, AtCmdUe, IphoneUe
from taf.internal.robot_typecasts import time_to_seconds


class ThroughputRunner(ThroughputValidation):
    def __init__(self, ues_configuration=None):
        """
        Constructor of UesController class. Provides interface for multi UE environment operations.
        Example __init__.py configuration of Android UE:

        _qualcomm = Android(
            ssh_connection_details=SshServiceDetails(
                addr="10.10.0.1",
                username="ue_pc_user",
                password="ue_pc_password",
            ),
            serial_number="ue_serial_number",
            server_dir="C:/pyro_server",
            python_path="C:/Python27/python.exe",
            iperf_details=_iperf,
            capabilities=["REAL_UE", "REAL_ANDROID_UE"],
        )

        :param ues_configuration:   contains all groups with assigned UEs e.g. ues_configuration={"all_ues": [0]} -
        group named 'all_ues' which contains one UE defined in first element (0 index) of tl.ues list
        :type  ues_configuration:   dict
        """
        super(ThroughputRunner, self).__init__(ues_configuration)
        self.set_data_transfer_parameters()
        self.airplane_mode_coordinates = {"all_ues": {"x": "500", "y": "800"}}

    @load_moler_configuration_from_tl()
    def attach_ues(self, ue_group="all_ues", wait_for_ues=True):
        """
        Attach all UEs in defined group.

        :param ue_group:      UEs group name defined in ues_configuration
        :type  ue_group:      str
        :param wait_for_ues:  If script should wait for attach of every ue in UEs group
        :type  wait_for_ues:  str
        :return:              None
        """
        for ue_id in self.ues_configuration[ue_group]:
            ue = self._get_ue_object(ue_id)
            ue.attach_ue(wait_for_ues)
        if self._get_available_ues(ue_group):
            logging.info("All UEs attached properly")

    @load_moler_configuration_from_tl()
    def detach_ues(self, ue_group="all_ues", wait_for_ues=True):
        """
        Detach all UEs in defined group.

        :param ue_group:   UEs group name defined in ues_configuration
        :type  ue_group:   str
        :param wait_for_ues:  If script should wait for attach of every ue in UEs group
        :type  wait_for_ues:  str
        :return:           None
        """
        for ue_id in self.ues_configuration[ue_group]:
            ue = self._get_ue_object(ue_id)
            ue.detach_ue(wait_for_ues)

    @load_moler_configuration_from_tl()
    def run_dl_traffic_with_ues_simultaneously(self, duration, ue_group="all_ues"):
        """
        Run DL traffic on all UEs defined in group with provided parameters.

        :param duration:   data transfer duration e.g. 100s
        :type  duration:   str
        :param ue_group:   UEs group name defined in ues_configuration
        :type  ue_group:   str
        :return:           None
        """
        duration = time_to_seconds(duration)
        for ue in self._get_available_ues(ue_group):
            if self.data_transfer_params["dedicated_bearer_port"]:
                DataTransfer(ue).run_data_transfer(self.data_transfer_params, duration, "DL", False)
                self.data_transfer_params["dedicated_bearer_port"] = None
            DataTransfer(ue).run_data_transfer(self.data_transfer_params, duration, "DL", False)
        time.sleep(duration + 10)
        self.get_data_transfers_results()

    @load_moler_configuration_from_tl()
    def run_ul_traffic_with_ues_simultaneously(self, duration, ue_group="all_ues"):
        """
        Run UL traffic on all UEs defined in group with provided parameters.

        :param duration:   data transfer duration e.g. 100s
        :type  duration:   str
        :param ue_group:   UEs group name defined in ues_configuration
        :type  ue_group:   str
        :return:           None
        """
        duration = time_to_seconds(duration)
        for ue in self._get_available_ues(ue_group):
            if self.data_transfer_params["dedicated_bearer_port"]:
                DataTransfer(ue).run_data_transfer(self.data_transfer_params, duration, "UL", False)
                self.data_transfer_params["dedicated_bearer_port"] = None
            DataTransfer(ue).run_data_transfer(self.data_transfer_params, duration, "UL", False)
        time.sleep(duration + 10)
        self.get_data_transfers_results()

    @load_moler_configuration_from_tl()
    def run_bi_dir_traffic_with_ues_simultaneously(self, duration, ue_group="all_ues"):
        """
        Run bidirectional traffic on all UEs defined in group with provided parameters.

        :param duration:   data transfer duration e.g. 100s
        :type  duration:   str
        :param ue_group:   UEs group name defined in ues_configuration
        :type  ue_group:   str
        :return:           None
        """
        duration = time_to_seconds(duration)
        for ue in self._get_available_ues(ue_group):
            if self.data_transfer_params["dedicated_bearer_port"]:
                DataTransfer(ue).run_data_transfer(self.data_transfer_params, duration, "UL", False)
                DataTransfer(ue).run_data_transfer(self.data_transfer_params, duration, "DL", False)
                self.data_transfer_params["dedicated_bearer_port"] = None
            DataTransfer(ue).run_data_transfer(self.data_transfer_params, duration, "UL", False)
            DataTransfer(ue).run_data_transfer(self.data_transfer_params, duration, "DL", False)
        time.sleep(duration + 10)
        self.get_data_transfers_results()

    def set_data_transfer_parameters(self, protocol="udp", server_buffer_dl="8M", client_buffer_dl="2M",
                                     buffer_len_dl="1400B", parallel_streams_dl="2", data_size_dl="400M",
                                     buffer_ul="2M", buffer_len_ul="1200B", parallel_streams_ul="1",
                                     data_size_ul="200M", congestion="", dedicated_bearer_port=None,
                                     maximum_segment_size=None):
        """
        Set actual iperf commands parameters.

        :param protocol:             udp or tcp
        :type  protocol:             str
        :param server_buffer_dl:     e.g. 8M
        :type  server_buffer_dl:     str
        :param client_buffer_dl:     e.g. 2M
        :type  client_buffer_dl:     str
        :param buffer_len_dl:        e.g. 1400B
        :type  buffer_len_dl:        str
        :param parallel_streams_dl:  e.g. 2
        :type  parallel_streams_dl:  str
        :param data_size_dl:         e.g. 500M
        :type  data_size_dl:         str
        :param buffer_ul:            e.g. 2M
        :type  buffer_ul:            str
        :param buffer_len_ul:        e.g. 1800B
        :type  buffer_len_ul:        str
        :param parallel_streams_ul:  e.g. 2
        :type  parallel_streams_ul:  str
        :param data_size_ul:         e.g. 100M
        :type  data_size_ul:         str
        :param congestion:           e.g. reno
        :type  congestion:           str
        :param dedicated_bearer_port: port id for dedicated bearer e.g. 9991
        :type  dedicated_bearer_port: str
        :param maximum_segment_size: bytes, tcp maximum segment size e.g. 40
        :type  maximum_segment_size: str
        :return:                     None
        """
        self.data_transfer_params = {
            "protocol": protocol,
            "server_buffer_dl": server_buffer_dl,
            "client_buffer_dl": client_buffer_dl,
            "buffer_len_dl": buffer_len_dl,
            "parallel_streams_dl": parallel_streams_dl,
            "data_size_dl": data_size_dl,
            "buffer_ul": buffer_ul,
            "buffer_len_ul": buffer_len_ul,
            "parallel_streams_ul": parallel_streams_ul,
            "data_size_ul": data_size_ul,
            "congestion": congestion,
            "dedicated_bearer_port": dedicated_bearer_port,
            "maximum_segment_size": maximum_segment_size}

    def set_custom_airplane_mode_tap_coordinates(self, x, y, ue_group="all_ues"):
        """
        Set custom airplane mode coordinates for use it with tap adb cmd. In order to set them properly
        check airplane mode icon location after 'adb shell am start -a android.settings.AIRPLANE_MODE_SETTINGS'
        cmd with usage of pointer location setting.

        :param ue_group:      UEs group name defined in ues_configuration
        :type  ue_group:      str
        :param x:             x axis pointer location
        :type  x:             int
        :param y:             y axis pointer location
        :type  y:             int
        :return:              None
        """
        self.airplane_mode_coordinates[ue_group] = {"x": str(x), "y": str(y)}

    def _get_available_ues(self, ue_group):
        available_ues = []
        for ue_id in self.ues_configuration[ue_group]:
            try:
                ue = self._get_ue_object(ue_id)
                ue_ip_address = ue.get_ue_ip()
                if ue_ip_address:
                    available_ues.append(ue)
                else:
                    logging.error("UE {} cannot get IP".format(ue_id))
                    continue
            except MolerException:
                continue
        if available_ues:
            return available_ues
        else:
            raise NoAvailableUesException

    def _get_ue_object(self, ue_id):
        if "REAL_ANDROID_UE" in list(get_builtin_value("tl.ues[{}].capabilities".format(ue_id))):
            return AndroidUe(ue_id=ue_id,
                             airplane_mode_coordinates=self.airplane_mode_coordinates[self._get_ue_group(ue_id)])
        elif "AT_CMD_UE" in list(get_builtin_value("tl.ues[{}].capabilities".format(ue_id))):
            return AtCmdUe(ue_id=ue_id)
        elif "IPHONE_UE" in list(get_builtin_value("tl.ues[{}].capabilities".format(ue_id))):
            return IphoneUe(ue_id=ue_id)
        else:
            raise UnknownUeType

    def _get_ue_group(self, ue_id):
        for ue_group_name in list(self.ues_configuration.keys()):
            if ue_id in self.ues_configuration[ue_group_name]:
                return ue_group_name


class DataTransfer:
    """Class for iperf data transfers handling"""

    def __init__(self, ue):
        self.ue = ue
        self.ue_pc_iperf = None
        self.ue_app_server = None

    def run_data_transfer(self, data_transfer_params, duration, direction, wait_for_finish):
        self._create_data_transfer_connections(data_transfer_params, direction)
        log_file = "/tmp/{}_{}_{}_{}_moler_iperf.txt".format(self.ue.serial_number, datetime.today().
                                                             strftime("%Y-%m-%d_%H:%M:%S"), direction,
                                                             data_transfer_params["protocol"])
        if direction == "DL":
            server_cmd, client_cmd = self._generate_dl_iperf_cmds(data_transfer_params, duration)
            server_cmd = "{} > {}".format(self.ue.iperf_launcher.format(server_cmd), log_file)
            iperf_server = self.ue_pc_iperf.get_cmd(cmd_name="run_script", cmd_params={'script_command': server_cmd})
            iperf_client = self.ue_app_server.get_cmd(cmd_name="run_script", cmd_params={'script_command': client_cmd})
        else:
            server_cmd, client_cmd = self._generate_ul_iperf_cmds(data_transfer_params, duration)
            server_cmd = "{} > {}".format(server_cmd, log_file)
            client_cmd = self.ue.iperf_launcher.format(client_cmd)
            iperf_server = self.ue_app_server.get_cmd(cmd_name="run_script",
                                                      cmd_params={'script_command': server_cmd})
            iperf_client = self.ue_pc_iperf.get_cmd(cmd_name="run_script", cmd_params={'script_command': client_cmd})
        self._run_iperf_cmds(iperf_server, iperf_client, duration, wait_for_finish)

    def _create_data_transfer_connections(self, data_transfer_params, direction):
        if data_transfer_params["dedicated_bearer_port"]:
            self.ue_pc_iperf = DeviceFactory.get_cloned_device(
                "UE{}_PC".format(self.ue.id),
                "UE{}_PC_{}_{}".format(self.ue.id, direction, data_transfer_params["dedicated_bearer_port"]),
                initial_state="UNIX_REMOTE")
            self.ue_app_server = DeviceFactory.get_cloned_device(
                "APP_SERVER{}".format(self.ue.id),
                "APP_SERVER{}_{}_{}".format(self.ue.id, direction, data_transfer_params["dedicated_bearer_port"]),
                initial_state="UNIX_REMOTE")
        else:
            self.ue_pc_iperf = DeviceFactory.get_cloned_device("UE{}_PC".format(self.ue.id),
                                                               "UE{}_PC_{}".format(self.ue.id, direction),
                                                               initial_state="UNIX_REMOTE")
            self.ue_app_server = DeviceFactory.get_cloned_device("APP_SERVER{}".format(self.ue.id),
                                                                 "APP_SERVER{}_{}".format(self.ue.id, direction),
                                                                 initial_state="UNIX_REMOTE")

    def _run_iperf_cmds(self, iperf_server, iperf_client, duration, wait_for_finish):
        try:
            iperf_server.start(timeout=duration + 20)
            time.sleep(3)
            iperf_client.start(timeout=duration + 20)
            if wait_for_finish:
                iperf_server.await_done()
                iperf_client.await_done()
        except Exception as e:
            logging.warning("Exception occurred in data transfer on UE{}: {}".format(self.ue.serial_number, e))

    _re_data_size = r'(?P<VALUE>\d*)(?P<UNIT>K|M|G)'

    def _generate_dl_iperf_cmds(self, data_transfer_params, duration):
        port = data_transfer_params["dedicated_bearer_port"] if data_transfer_params["dedicated_bearer_port"] else \
            str(random.randint(50000, 60000))
        protocol = "-u" if data_transfer_params["protocol"] == "udp" else ""
        congestion = "-Z {}".format(data_transfer_params["congestion"]) if data_transfer_params["congestion"] else ""
        maximum_segment_size = "-M {}".format(data_transfer_params["maximum_segment_size"])\
            if data_transfer_params["maximum_segment_size"] else ""
        server_buffer = "-w {}".format(data_transfer_params["server_buffer_dl"]) if data_transfer_params[
            "server_buffer_dl"] else ""
        client_buffer = "-w {}".format(data_transfer_params["client_buffer_dl"]) if data_transfer_params[
            "client_buffer_dl"] else ""
        buffer_len = "-l {}".format(data_transfer_params["buffer_len_dl"]) if data_transfer_params[
            "buffer_len_dl"] else ""
        parallel_streams = "-P {}".format(data_transfer_params["parallel_streams_dl"])
        data_size_dl = re.search(DataTransfer._re_data_size, data_transfer_params["data_size_dl"]) if \
            data_transfer_params["data_size_dl"] else ""
        data_size = "-b {}{}".format(float(data_size_dl.group('VALUE')) / int(
            data_transfer_params["parallel_streams_dl"]), data_size_dl.group('UNIT')) if data_transfer_params[
            "data_size_dl"] else ""
        duration = str(int(duration) + 3)
        srv_cmd = "iperf -s {} -p {} -i 1 {} -t {}".format(protocol, port, server_buffer, str(int(duration) + 3))
        cli_cmd = "iperf -c {} {} {} -p {} -t {} -i 1 -B {} {} {} {} {} {}". \
            format(self.ue.ip_address, protocol, data_size, port, duration, self.ue.app_server_traffic_interface,
                   parallel_streams, client_buffer, buffer_len, congestion, maximum_segment_size)

        return srv_cmd, cli_cmd

    def _generate_ul_iperf_cmds(self, data_transfer_params, duration):
        port = data_transfer_params["dedicated_bearer_port"] if data_transfer_params["dedicated_bearer_port"] else \
            str(random.randint(50000, 60000))
        protocol = "-u" if data_transfer_params["protocol"] == "udp" else ""
        congestion = "-Z {}".format(data_transfer_params["congestion"]) if data_transfer_params["congestion"] else ""
        maximum_segment_size = "-M {}".format(data_transfer_params["maximum_segment_size"])\
            if data_transfer_params["maximum_segment_size"] else ""
        buffer_ul = "-w {}".format(data_transfer_params["buffer_ul"]) if data_transfer_params["buffer_ul"] else ""
        buffer_len = "-l {}".format(data_transfer_params["buffer_len_ul"]) if data_transfer_params[
            "buffer_len_ul"] else ""
        parallel_streams = "-P {}".format(data_transfer_params["parallel_streams_ul"])
        data_size_ul = re.search(DataTransfer._re_data_size, data_transfer_params["data_size_ul"]) if \
            data_transfer_params["data_size_ul"] else ""
        data_size = "-b {}{}".format(float(data_size_ul.group('VALUE')) / int(
            data_transfer_params["parallel_streams_ul"]), data_size_ul.group('UNIT')) if data_transfer_params[
            "data_size_ul"] else ""
        cli_cmd = "iperf -c {} {} {} -p {} -t {} -i 1 {} {} {} {} {}". \
            format(self.ue.app_server_traffic_interface, protocol, data_size, port, duration, parallel_streams,
                   buffer_ul, buffer_len, congestion, maximum_segment_size)
        srv_cmd = "iperf -s {} -p {} -i 1 -B {} {} -t {}" \
            .format(protocol, port, self.ue.app_server_traffic_interface, buffer_ul, str(int(duration) + 3))

        return srv_cmd, cli_cmd
